          {"type": "text", "text": "7 Perguntas Frequentes Sobre Preço de Site Odontológico"}
        ]
      },
      {
        "type": "heading",
        "attrs": {"level": 3},
        "content": [
          {"type": "text", "text": "1. Por que sites para dentistas custam mais que sites genéricos?"}
        ]
      },
      {
        "type": "paragraph",
        "content": [
          {"type": "text", "text": "Sites odontológicos precisam de elementos específicos que sites genéricos não têm: integração com WhatsApp Business, formulários em conformidade com LGPD, seções especializadas para listar procedimentos (implantes, ortodontia, clareamento), área de depoimentos estruturada, galeria de fotos do consultório, e design que transmita credibilidade médica. Um site genérico de R$ 500 não entende essas necessidades do setor de saúde."}
        ]
      },
      {
        "type": "heading",
        "attrs": {"level": 3},
        "content": [
          {"type": "text", "text": "2. Posso fazer meu site de graça usando Instagram ou Facebook?"}
        ]
