      {
        "type": "paragraph",
        "content": [
          {"type": "text", "text": "Instagram e Facebook são fundamentais para engajamento, mas "},
          {"type": "text", "marks": [{"type": "bold"}],
            "text": "NÃO substituem um site profissional"
          },
          {"type": "text", "text": ". Motivos: (1) Você não aparece no Google quando pacientes buscam 'dentista + sua cidade', (2) Não tem controle (algoritmo muda, conta pode ser suspensa sem aviso), (3) Dados mostram que 78% dos brasileiros procuram 'dentista [cidade]' no Google ANTES de ir ao Instagram, (4) Redes sociais não transmitem a mesma credibilidade profissional que um site próprio."}
        ]
      },
      {
        "type": "heading",
        "attrs": {"level": 3},
        "content": [
          {"type": "text", "text": "3. Quanto tempo leva para o site começar a trazer pacientes novos?"}
        ]
      },
      {
        "type": "paragraph",
        "content": [
          {"type": "text", "text": "Depende da estratégia: Com SEO orgânico (incluído no nosso plano): 30-90 dias para começar a aparecer no Google. Com Google Meu Negócio otimizado (ensinamos como fazer grátis): 7-14 dias para primeiros contatos. Com tráfego pago (Google Ads, que você pode fazer sozinho): resultados imediatos. Dados dos nossos 127 clientes: 68% relatam o primeiro paciente vindo do site entre 15-45 dias."}
        ]
      },
      {
        "type": "heading",
        "attrs": {"level": 3},
        "content": [
          {"type": "text", "text": "4. O que acontece se eu não gostar do site depois de pronto?"}
        ]
      },
      {
        "type": "paragraph",
        "content": [
