    {
      "type": "heading",
      "attrs": {"level": 2},
      "content": [{"type": "text", "text": "15 Perguntas Frequentes"}]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "1. Quanto custa fazer marketing digital?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "De R$ 0 (100% orgânico) a R$ 5.000+/mês (estratégia completa com agência + Ads). Iniciantes: comece com R$ 200-500/mês (GMB grátis + site pronto)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "2. Quanto tempo para ver resultados?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "GMB: 2-4 semanas | Instagram: 2-3 meses | SEO: 4-6 meses | Google Ads: imediato (mas precisa otimizar)"}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "3. Preciso contratar agência?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Não obrigatório. Faça você mesmo se: tem tempo (10h/semana), gosta de aprender, orçamento limitado. Contrate se: fatura R$ 30k+/mês, quer escalar rápido, não tem tempo."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "4. Posso fazer sozinho?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Sim! 70% dos casos de sucesso começaram DIY (faça você mesmo). Use este guia + ferramentas gratuitas."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "5. Vale a pena investir em Google Ads?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Só se: GMB 100% otimizado, site profissional, orçamento R$ 1.000+/mês, sabe calcular ROI. Caso contrário, foque em orgânico primeiro."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "6. Como medir ROI?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Fórmula: (Faturamento de novos pacientes - Investimento marketing) ÷ Investimento × 100. Exemplo: Ganhou R$ 10k, investiu R$ 500 → ROI = 1.900%"}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "7. Quanto gastar em cada canal?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "GMB: R$ 0 | Site: R$ 200-500/mês | Instagram: R$ 0-500/mês | Google Ads: R$ 1.000-3.000/mês (opcional)"}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "8. Instagram ou Facebook?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Instagram (prioridade). Público 25-45 anos, mais engajamento, melhor para dentistas. Facebook: complementar (público 45+)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "9. Preciso de blog?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Não obrigatório, mas recomendado (SEO longo prazo). Se tiver, publique 2-4 artigos/mês."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "10. Como não violar CFO?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Nunca: garantir resultados, sensacionalismo, comparar concorrentes. Sempre: mostrar CRO, pedir autorização para antes/depois, ser ético."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "11. E-mail marketing funciona?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Sim, mas para pacientes atuais (lembrete limpeza, promoções). Taxa abertura: 20-30%. WhatsApp é melhor (98% abertura)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "12. TikTok vale a pena?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Depende do público. Se atende jovens (18-25), sim. Para público geral, Instagram é melhor."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "13. Como conseguir primeiros 1.000 seguidores?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Convide pacientes atuais, familiares, amigos → Poste 5x/semana (educativo) → Use hashtags locais (#dentistasp) → Faça Reels (alcance 10x maior)"}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "14. Como automatizar atendimento?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "WhatsApp Business (mensagens automáticas grátis) ou ManyChat (R$ 60/mês, automação avançada com chatbot)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "15. Qual a taxa de conversão ideal?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "GMB: 8-12% (visualizações → ações) | Site: 2-5% (visitas → agendamentos) | Instagram: 1-3% (seguidores → pacientes/ano)"}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 2},
      "content": [{"type": "text", "text": "Conclusão: Seu Plano de Ação de 7 Dias"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Marketing digital não é mais opcional para dentistas em 2026. É "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "ESSENCIAL"},
        {"type": "text", "text": " para sobreviver e crescer."}
      ]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "📅 Seu Plano de Ação AGORA (7 Dias):"}]
    },
    {
      "type": "bulletList",
      "content": [
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 1:"}, {"type": "text", "text": " Criar/verificar perfil GMB"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 2:"}, {"type": "text", "text": " Preencher 100% GMB + criar WhatsApp Business"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 3:"}, {"type": "text", "text": " Contratar fotógrafo + definir site (pronto ou custom)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 4:"}, {"type": "text", "text": " Adicionar fotos ao GMB + pedir primeiras 10 avaliações"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 5:"}, {"type": "text", "text": " Lançar site + criar Instagram profissional"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Dia 6:"}, {"type": "text", "text": " Fazer 3 posts GMB + 7 posts Instagram"}]}]},
