      "content": [{"type": "text", "text": "10 Erros Fatais Que Afastam Pacientes"}]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "❌ 1. Site Que Não Abre no Celular"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Impacto:"},
        {"type": "text", "text": " 78% dos acessos são mobile. Se não funcionar no celular, você perde 8 em cada 10 pacientes."}
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Como testar:"},
        {"type": "text", "text": " Abra seu site no celular. Se precisar dar zoom ou rolar horizontalmente, está errado."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "❌ 2. Demora Mais de 5 Segundos para Carregar"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Impacto:"},
        {"type": "text", "text": " 53% dos visitantes abandonam sites que demoram +3 segundos."}
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Como testar:"},
        {"type": "text", "text": " Use PageSpeed Insights do Google. Nota abaixo de 50 = problema sério."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "❌ 3. Sem Informações de Contato Visíveis"}]
    },
    {
      "type": "paragraph",
      "content": [
