    {
      "type": "heading",
      "attrs": {"level": 2},
      "content": [{"type": "text", "text": "Perguntas Frequentes (FAQs)"}]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "1. Preciso mesmo de site se tenho Instagram ativo?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "SIM."},
        {"type": "text", "text": " Instagram atrai, mas site convence e converte. 73% dos pacientes não agendam procedimentos caros sem ver um site profissional. São complementares, não excludentes."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "2. Quanto tempo leva para criar um site?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Depende: Wix/WordPress (você mesmo): 2-4 semanas. Freelancer: 3-8 semanas. Agência: 2-3 meses. "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "Sites Odonto: 7 dias úteis."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "3. Preciso pagar mensalidade?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Depende da opção. Wix/WordPress: R$ 45-100/mês. Agências: R$ 200-500/mês. "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "Sites Odonto: R$ 0/mês (hospedagem gratuita para sempre)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "4. Meu site vai aparecer no Google?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Se tiver SEO bem feito, sim."},
        {"type": "text", "text": " Mas leva 3-6 meses. Wix/WordPress gratuitos têm SEO ruim. Sites profissionais com SEO on-page ranqueiam bem. Combine com Google Meu Negócio para resultados rápidos."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "5. Posso atualizar o site sozinho depois?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Depende da tecnologia. WordPress: sim (com treinamento). Sites custom: precisa de dev. "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "Sites Odonto: atualizações básicas via suporte (incluído)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "6. Preciso ter domínio próprio?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "SIM."},
        {"type": "text", "text": " Domínio gratuito tipo 'seusite.wixsite.com' é amador. Compre um domínio próprio: seunomedentista.com.br (R$ 40/ano). Transmite profissionalismo."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "7. Wix ou WordPress: qual é melhor?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "WordPress."},
        {"type": "text", "text": " Wix é mais fácil mas tem SEO ruim e você não é dono. WordPress é mais poderoso, melhor SEO, mas precisa de conhecimento técnico. Ideal: contratar profissional que use WordPress."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "8. Vale a pena contratar agência cara?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Só se você tiver orçamento (R$ 5k+) e tempo (2-3 meses). Para 90% dos dentistas, "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "solução especializada como Sites Odonto"},
        {"type": "text", "text": " entrega 80% do resultado por 10% do preço."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "9. Meu primo faz site barato. Posso pedir para ele?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Pode, mas cuidado. "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "70% dos sites de 'amigos' nunca ficam prontos"},
        {"type": "text", "text": " ou ficam mal feitos. Se contratar, exija contrato, prazo e garantia. Barato que não funciona sai caro."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "10. Posso usar fotos do Google no meu site?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "NÃO."},
        {"type": "text", "text": " Direitos autorais. Use fotos reais do seu consultório ou bancos gratuitos (Unsplash, Pexels). Fotos genéricas prejudicam credibilidade mesmo sendo 'bonitas'."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "11. Preciso ter blog no site?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Não é obrigatório, mas ajuda MUITO no SEO."},
        {"type": "text", "text": " Sites com blog têm 434% mais páginas indexadas no Google. Publique 1-2 artigos/mês sobre dúvidas comuns dos pacientes."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "12. Como escolher um bom desenvolvedor?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "5 perguntas essenciais:"}]
    },
    {
      "type": "bulletList",
      "content": [
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Tem portfólio de sites odontológicos? (conhece o nicho)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Hospedagem inclusa ou separada? (custo oculto?)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Quanto tempo de suporte pós-entrega?"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "O site será responsivo? (teste antes)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Inclui SEO básico? (meta tags, sitemap)"}]}]}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "13. Quanto devo gastar em anúncios depois do site pronto?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Comece com R$ 300-500/mês em Google Ads. Mas "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "primeiro otimize Google Meu Negócio (grátis)"},
        {"type": "text", "text": " e SEO orgânico. Anúncios aceleram, mas não substituem presença orgânica."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "14. Meu site antigo é ruim. Devo refazer ou reformar?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Se tem mais de 5 anos: "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "refaça do zero."},
        {"type": "text", "text": " Tecnologia mudou muito. Reformar site velho é como reformar Fusca - sai mais caro e nunca fica bom. Aproveite para migrar domínio pro site novo."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "15. Quanto tempo até ver retorno do investimento?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "1-3 meses."},
        {"type": "text", "text": " Primeira semana: pacientes atuais veem credibilidade. Primeiro mês: leads começam a vir do Google. 3 meses: ROI de 5-10x. Cases deste artigo tiveram ROI em 60-90 dias."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "16. Devo colocar preços no site?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Depende."},
        {"type": "text", "text": " Procedimentos simples (limpeza): sim ('A partir de R$ 150'). Procedimentos complexos (implante): não ('Orçamento personalizado'). Transparência gera confiança, mas cada caso é único."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "17. Como proteger meu site de hackers?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "4 medidas essenciais:"}
      ]
    },
    {
      "type": "bulletList",
      "content": [
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "SSL ativo (https)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Senhas fortes (não use 'admin' ou '123456')"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Backup automático semanal"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Plugins/temas atualizados (se WordPress)"}]}]}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "18. Posso ter vários idiomas no site?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Pode, mas só faz sentido se você atende estrangeiros. "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "Foque primeiro em português impecável."},
        {"type": "text", "text": " Site multilíngue custa 2-3x mais e complica SEO. Prioridade: 1 idioma bem feito > 3 mal feitos."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "19. Preciso ter área de login para pacientes?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Não no início."},
        {"type": "text", "text": " Área de paciente é útil mas complexa (custos, manutenção, segurança LGPD). Comece com site institucional simples. Área de paciente vem depois, quando tiver +500 pacientes ativos."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "20. Qual a primeira coisa que devo fazer hoje?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Se não tem site: preencha o briefing da Sites Odonto agora."},
        {"type": "text", "text": " 10 minutos, zero compromisso até aprovar o layout. Você recebe em 7 dias e só paga se gostar."}
      ]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Se já tem site: faça os 5 testes gratuitos acima."},
