    },
    {
      "type": "heading",
      "attrs": {"level": 2},
      "content": [{"type": "text", "text": "Perguntas Frequentes (FAQs)"}]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "1. Quantas vezes por semana devo postar?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Ideal: 4-5 posts no feed + 5-10 stories diários."},
        {"type": "text", "text": " Se não conseguir, priorize Stories (onde está 70% do engajamento). Mínimo aceitável: 3 posts/semana + stories diários."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "2. Posso comprar seguidores?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "NÃO."},
        {"type": "text", "text": " O algoritmo detecta engajamento falso e penaliza seu alcance. 1.000 seguidores reais valem mais que 10.000 falsos. Foque em crescimento orgânico."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "3. Preciso mostrar meu rosto?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Altamente recomendado."},
        {"type": "text", "text": " Pacientes querem conhecer quem vai cuidar deles. Perfis com rosto do dentista convertem 3x mais. Se tem timidez, comece com Stories e vá ganhando confiança."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "4. Vale a pena investir em anúncios pagos (Instagram Ads)?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Sim, mas "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "depois de ter conteúdo orgânico sólido."},
        {"type": "text", "text": " Comece orgânico (0-3 meses), depois invista R$ 300-500/mês em Ads. ROI típico: 5-8x."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "5. Como conseguir autorização de pacientes para postar?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Tenha um "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "termo de autorização de imagem"},
        {"type": "text", "text": " simples. Peça assinatura na última consulta (quando paciente está feliz com resultado). Ofereça desconto (10% OFF) em troca da autorização."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "6. Melhor horário para postar?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Depende da sua audiência."},
        {"type": "text", "text": " Geral: 7h-9h (manhã), 12h-14h (almoço), 19h-21h (noite). Veja nos Insights qual horário SUA audiência está online."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "7. Quanto tempo até ver resultados?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "30-60 dias para primeiros agendamentos."},
        {"type": "text", "text": " 90 dias para fluxo constante. 6 meses para perfil consolidado. Paciência e consistência são chave."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "8. Preciso contratar social media?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "text": "Nos primeiros 3-6 meses, "},
        {"type": "text", "marks": [{"type": "bold"}], "text": "você mesmo pode fazer"},
        {"type": "text", "text": " (com este guia). Quando passar de 30 agendamentos/mês, vale contratar (R$ 800-1.500/mês)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "9. Posso repostar conteúdo de outros dentistas?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Ocasionalmente, sim."},
        {"type": "text", "text": " Mas 80% do conteúdo deve ser original. Reposte dando crédito claro. Foque em criar seu próprio conteúdo."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "10. Como lidar com comentários negativos?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Responda sempre, educadamente."},
        {"type": "text", "text": " Se for crítica construtiva, agradeça e explique. Se for ofensivo, delete e bloqueie. Nunca entre em discussões públicas."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "11. Devo ter Instagram pessoal e profissional separados?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Depende."},
        {"type": "text", "text": " Se você é o rosto da clínica (dentista solo), pode mesclar (70% profissional + 30% pessoal humanizado). Se for clínica com vários dentistas, mantenha separado."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "12. Como crescer mais rápido?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "3 atalhos legítimos:"},
        {"type": "text", "text": " (1) Reels virais (invista nisso), (2) Parcerias com influenciadores locais, (3) Colaborações com outros profissionais (ortodontista + periodontista)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "13. Vale a pena fazer lives?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Sim, mas só quando tiver +1.000 seguidores."},
        {"type": "text", "text": " Antes disso, foque em Reels e Stories. Lives são ótimas para Q&A (1x/mês)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "14. Como transformar seguidores em pacientes?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "CTA constante."},
        {"type": "text", "text": " Todo post/story deve ter call-to-action: 'DM para agendar', 'Link na bio', 'Últimas vagas da semana'. Facilite o contato (WhatsApp direto)."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "15. Posso postar procedimentos com sangue?"}]
    },
    {
      "type": "paragraph",
      "content": [
        {"type": "text", "marks": [{"type": "bold"}], "text": "Tecnicamente sim, mas não recomendo."},
        {"type": "text", "text": " Pode assustar pacientes. Prefira focar em resultados (antes e depois) sem mostrar procedimento invasivo."}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
