        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Implante Dentário:"}, {"type": "text", "text": " \"Recupere seu sorriso com implantes de titânio. Parcelamos em até 12x. Consulta gratuita.\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Aparelho Ortodôntico:"}, {"type": "text", "text": " \"Alinhadores invisíveis ou metálicos. Planos a partir de R$ 200/mês.\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Limpeza Profissional:"}, {"type": "text", "text": " \"Profilaxia completa + aplicação de flúor. R$ 150.\""}]}]}
