      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Olá! 😊 Obrigado por entrar em contato com a [Nome da Clínica].\n\nSou [Seu Nome], vou ajudar você a cuidar do seu sorriso!\n\nPara agilizar seu atendimento, me conta:\n1️⃣ Qual serviço você procura?\n2️⃣ Tem alguma preferência de horário?\n\nEstou online e vou te responder em instantes! ⚡"}]
