    {
      "type": "heading",
      "attrs": {"level": 2},
      "content": [{"type": "text", "text": "40+ Mensagens Prontas para Copiar e Usar"}]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "💬 Categoria 1: Primeiro Contato (10 mensagens)"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "1. Resposta Inicial Geral:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Olá [Nome]! 😊 Muito obrigado pelo contato!\n\nSou [Seu Nome], da equipe [Clínica].\nFico feliz em ajudar você a cuidar do seu sorriso!\n\nPara eu entender melhor sua necessidade:\n• Qual procedimento você procura?\n• Tem alguma dor ou urgência?\n• Qual melhor dia/horário para você?\n\nEstou aqui para te atender! 💙"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "2. Lead Vindo do Instagram:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Oi [Nome]! Vi que você veio do nosso Instagram! 📱\n\nQue legal te ter por aqui!\n\nVocê se interessou por algum serviço específico que viu por lá?\nClareamento, Implantes, Ortodontia...?\n\nConta pra mim que já vou te ajudar! 😊"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "3. Lead Vindo do Google:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Olá! Obrigado por nos encontrar no Google! 🔍\n\nFicamos muito felizes com seu contato.\n\nPara eu te ajudar melhor:\n1️⃣ Qual tratamento você procura?\n2️⃣ Já é paciente ou é primeira vez?\n3️⃣ Prefere manhã ou tarde?\n\nVou te passar todas as informações! ✅"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "4. Resposta Rápida (5 min):"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Oi! Vi sua mensagem e já estou te atendendo! ⚡\n\nSó um minutinho que vou buscar as informações certinhas pra você.\n\nJá volto! 😊"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "5. Retorno Após Ausência:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Oi [Nome]! Desculpe a demora para responder! 🙏\n\nEstávamos em atendimento, mas agora estou 100% disponível para você.\n\nVamos retomar: você estava interessado(a) em [serviço].\nPosso te ajudar com mais informações?\n\nEstou online agora! 💬"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "6-10. Modelos por Especialidade:"}]
    },
    {
      "type": "bulletList",
      "content": [
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Clareamento:"}, {"type": "text", "text": " \"Quer um sorriso até 8 tons mais branco? Nosso clareamento é seguro, rápido e sem sensibilidade! Posso te enviar fotos de antes/depois?\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Implante:"}, {"type": "text", "text": " \"Falta algum dente? Com implantes você volta a sorrir e mastigar sem vergonha! Temos simulação 3D gratuita. Quer agendar?\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Ortodontia:"}, {"type": "text", "text": " \"Quer alinhar os dentes? Temos aparelhos invisíveis e metálicos! Posso te mostrar as opções e valores?\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Urgência/Dor:"}, {"type": "text", "text": " \"Entendo que está com dor. Vamos te encaixar hoje ainda! Qual horário você consegue vir? Temos disponibilidade às [horários].\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Check-up:"}, {"type": "text", "text": " \"Que bom que cuida da prevenção! Nossa limpeza completa inclui profilaxia + flúor. Quer agendar?\""}]}]}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "💰 Categoria 2: Orçamento e Valores (10 mensagens)"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "11. Quando Perguntam Valor Direto:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Ótima pergunta sobre valores! 💰\n\nPara te passar um orçamento certinho, preciso entender seu caso:\n\n• Já fez esse tratamento antes?\n• Tem alguma radiografia recente?\n• Prefere pagar à vista ou parcelado?\n\nCom essas infos, monto um orçamento personalizado pra você!\n\nOu se preferir, agenda uma avaliação GRATUITA e o dentista te explica tudo. Que tal?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "12. Valores de Clareamento:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Clareamento Dental 🦷✨\n\n📋 Opções:\n• Caseiro (moldeira): R$ 600 (até 12x)\n• Consultório (1 sessão): R$ 900 (até 12x)\n• Combo (caseiro + consultório): R$ 1.200 (até 12x)\n\nResultado: até 8 tons mais branco!\n\n🎁 BÔNUS: Avaliação + limpeza gratuitas\n\nQual opção te interessa mais?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "13. Valores de Implante:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Implante Dentário 🦷\n\n📋 Investimento:\n• Implante unitário: R$ 2.800 (até 12x de R$ 280)\n• Inclui: pino + coroa + acompanhamento\n\n✅ DIFERENCIAIS:\n→ Implantes importados (Suíça)\n→ Garantia de 5 anos\n→ Tomografia 3D gratuita\n→ Avaliação sem compromisso\n\nPosso agendar sua avaliação?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "14. Quando Acham Caro:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Entendo sua preocupação com o valor! 💙\n\nVou ser transparente: investir em saúde bucal é cuidar de você!\n\nPara facilitar:\n💳 Parcelamos em até 12x sem juros\n🎁 Avaliação gratuita (sem compromisso)\n💰 Desconto de 10% à vista\n\nAlém disso, compare: gastar R$ [X] agora evita problemas de R$ [X*3] no futuro.\n\nQue tal marcar a avaliação gratuita? Aí você decide com calma! 😊"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "15-20. Outros Orçamentos:"}]
    },
    {
      "type": "bulletList",
      "content": [
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Aparelho ortodôntico:"}, {"type": "text", "text": " \"A partir de R$ 200/mês. Inclui manutenções mensais. Duração: 18-24 meses.\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Lente de contato dental:"}, {"type": "text", "text": " \"R$ 1.800 por dente. Transformação completa do sorriso! Fotos de casos reais: [link]\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Limpeza:"}, {"type": "text", "text": " \"R$ 150 (inclui profilaxia, flúor e orientações). Agende a cada 6 meses!\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Canal:"}, {"type": "text", "text": " \"Entre R$ 600-1.200 (depende do dente). Avaliação gratuita!\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Extração siso:"}, {"type": "text", "text": " \"R$ 300 por dente. Sedação disponível (+ R$ 200).\""}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "Prótese:"}, {"type": "text", "text": " \"Depende do tipo. Agende avaliação gratuita que te mostro as opções!\""}]}]}
      ]
    },
    {
      "type": "heading",
      "attrs": {"level": 3},
      "content": [{"type": "text", "text": "📅 Categoria 3: Agendamento (10 mensagens)"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "21. Oferecer Horários:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Perfeito! Vamos agendar! 📅\n\nTenho disponibilidade esta semana:\n\n🗓️ Terça (21/01): 14h ou 16h\n🗓️ Quarta (22/01): 10h ou 15h\n🗓️ Quinta (23/01): 9h ou 17h\n\nQual melhor para você?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "22. Confirmação de Agendamento:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "✅ AGENDAMENTO CONFIRMADO!\n\n👤 Paciente: [Nome]\n📅 Data: [Dia/Mês] às [Hora]\n🏥 Procedimento: [Serviço]\n📍 Local: [Endereço]\n\n📋 IMPORTANTE:\n• Chegue 10 min antes\n• Traga documento com foto\n• Traga exames (se tiver)\n\n💬 Vou te enviar um lembrete 1 dia antes!\n\nQualquer dúvida, estou aqui! 😊"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "23. Lembrete 24h Antes:"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Oi [Nome]! Lembrete amigável! ⏰\n\nSua consulta é AMANHÃ:\n📅 [Dia] às [Hora]\n📍 [Endereço]\n\nVocê confirma presença?\n\nResponda SIM para confirmar ou me avise se precisar reagendar!\n\nNos vemos em breve! 💙"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "24. Reagendamento (Paciente Pediu):"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Sem problemas! Entendo que imprevistos acontecem. 😊\n\nVamos reagendar:\n\n🗓️ Próxima semana:\n• Segunda: 9h, 14h\n• Terça: 10h, 16h\n• Quinta: 15h, 17h\n\nQual desses horários funciona melhor pra você?"}]
    },
    {
      "type": "paragraph",
      "content": [{"type": "text", "marks": [{"type": "bold"}], "text": "25. Quando Não Confirma (2h antes):"}]
    },
    {
      "type": "codeBlock",
      "attrs": {"language": null},
      "content": [{"type": "text", "text": "Oi [Nome]! 😊\n\nNão vi sua confirmação.\nSua consulta é HOJE às [Hora].\n\nVocê vem? 🤔\n\nPor favor, confirme para eu reservar seu horário!\n\nSe não conseguir vir, me avise para não perdermos a vaga. 🙏"}]
