        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Só adicione em listas quem autorizou"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Não use automação não oficial (bots piratas)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Respeite horários (não mande mensagem 23h)"}]}]},
        {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Sempre ofereça opção de sair da lista"}]}]}
